import{_ as n,o as i,c as e,a5 as o}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Studio Plans — Gói trả phí cho công ty Personal","description":"","frontmatter":{},"headers":[],"relativePath":"feature/studio-personal-plans/spec.md","filePath":"feature/studio-personal-plans/spec.md"}'),d={name:"feature/studio-personal-plans/spec.md"};function c(h,t,a,r,g,l){return i(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="studio-plans-—-goi-tra-phi-cho-cong-ty-personal" tabindex="-1">Studio Plans — Gói trả phí cho công ty Personal <a class="header-anchor" href="#studio-plans-—-goi-tra-phi-cho-cong-ty-personal" aria-label="Permalink to &quot;Studio Plans — Gói trả phí cho công ty Personal&quot;">​</a></h1><p>&gt; FR liên quan: 3.9.1 Upgrade Plan, 3.9.2 Renew Plan, 3.9.5 Buy Credit, 3.4.x Create Workspace / Invite Member. &gt; Quyết định nghiệp vụ chốt với chủ dự án ngày 2026-11-22. &gt; Thay thế phần &quot;Personal proposal&quot; của <code>subscription-four-plan-catalog</code> (gói <code>PERSONAL</code> scope USER giữ nguyên, không bán).</p><h2 id="_1-objective" tabindex="-1">1. Objective <a class="header-anchor" href="#_1-objective" aria-label="Permalink to &quot;1. Objective&quot;">​</a></h2><p>Personal là nguồn doanh thu chính lúc ra mắt, nhưng hiện chưa có đường thu tiền: công ty Personal đang bị gán gói BASIC của Agency (0 credit, 3 thành viên, 5 khách hàng), và muốn nâng cấp chỉ có Agency Plus 990k. Gói <code>PERSONAL</code> cũ trong DB không bán được.</p><p>Mục tiêu: một dòng gói riêng <strong>Studio</strong> cho công ty <code>company_type = PERSONAL</code>, giá theo thị trường cá nhân VN (Google AI Plus 132k, CapCut Pro ~290k, Canva Pro ~250-330k), lãi ≥ 60% kể cả khi người dùng đốt hết credit vào video.</p><h2 id="_2-bang-goi-chot" tabindex="-1">2. Bảng gói (chốt) <a class="header-anchor" href="#_2-bang-goi-chot" aria-label="Permalink to &quot;2. Bảng gói (chốt)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Quyền lợi</th><th>Studio Free</th><th>Studio Plus</th><th>Studio Pro</th></tr></thead><tbody><tr><td>Mã gói (<code>code</code>)</td><td><code>STUDIO_FREE</code></td><td><code>STUDIO_PLUS</code></td><td><code>STUDIO_PRO</code></td></tr><tr><td>Giá / tháng</td><td>0đ</td><td>99.000đ</td><td>299.000đ</td></tr><tr><td>Trả trước 3 / 6 / 12 tháng</td><td>—</td><td>279k / 529k / 949k</td><td>849k / 1.599k / 2.869k</td></tr><tr><td>Không gian cá nhân</td><td>1</td><td>3</td><td>10</td></tr><tr><td>Người dùng</td><td>chỉ chủ</td><td>chỉ chủ</td><td>chủ + 2 Creator</td></tr><tr><td>Plan credit / tháng</td><td>100</td><td>900</td><td>2.400</td></tr><tr><td>Lưu trữ</td><td>2 GB</td><td>5 GB</td><td>30 GB</td></tr><tr><td>Tác vụ AI song song</td><td>1</td><td>1</td><td>2</td></tr><tr><td>Lịch sử hoạt động</td><td>30 ngày</td><td>90 ngày</td><td>180 ngày</td></tr><tr><td>Lịch sử phiên bản</td><td>7 ngày</td><td>30 ngày</td><td>90 ngày</td></tr><tr><td>Thùng rác</td><td>7 ngày</td><td>30 ngày</td><td>30 ngày</td></tr><tr><td>Khách hàng / Client Portal</td><td>không</td><td>không</td><td>không</td></tr><tr><td>Mua thêm credit (3.9.5)</td><td>có</td><td>có</td><td>có</td></tr></tbody></table><p>Cơ sở giá (sheet &quot;Chi phí &quot; — Business &amp; Finance.xlsx, tỷ giá 25.726đ/USD): credit đắt nhất = video 32,2đ/credit; AI text 1.443đ/người/tháng; S3 643đ/GB/tháng.</p><table tabindex="0"><thead><tr><th>Gói</th><th>Chi phí tối đa / tháng</th><th>Lãi sau phí cổng 3,5%</th></tr></thead><tbody><tr><td>Studio Free</td><td>~3k (100 credit không đủ 1 video, credit hết hạn cuối kỳ)</td><td>—</td></tr><tr><td>Studio Plus</td><td>33,6k</td><td>62,6%</td></tr><tr><td>Studio Pro</td><td>100,9k</td><td>62,8%</td></tr></tbody></table><p>Hòa vốn chi phí cố định 7,66 triệu/tháng ≈ 70 Plus hoặc 25 Pro (theo mức dùng thực tế).</p><h2 id="_3-user-stories" tabindex="-1">3. User Stories <a class="header-anchor" href="#_3-user-stories" aria-label="Permalink to &quot;3. User Stories&quot;">​</a></h2><ul><li>US1. Là chủ công ty Personal mới, tôi được cấp ngay Studio Free, không thấy gì về Agency.</li><li>US2. Là chủ công ty Personal, ở trang Gói tôi chỉ thấy 3 gói Studio và mua Plus/Pro qua SePay.</li><li>US3. Đang ở Studio Plus, tôi lên Studio Pro ngay và chỉ trả phần chênh lệch theo ngày còn lại.</li><li>US4. Gói Studio hết hạn thì tôi tự về Studio Free (không về Agency Basic).</li><li>US5. Vượt số không gian / thành viên của gói thì tôi bị chặn kèm gợi ý nâng cấp.</li><li>US6. Là chủ Agency, tôi không thấy và không mua được gói Studio (và ngược lại).</li></ul><h2 id="_4-acceptance-criteria" tabindex="-1">4. Acceptance Criteria <a class="header-anchor" href="#_4-acceptance-criteria" aria-label="Permalink to &quot;4. Acceptance Criteria&quot;">​</a></h2><ul><li>AC1. Tạo công ty <code>PERSONAL</code> (form, chooser, bootstrap) → subscription <code>STUDIO_FREE</code>, ví credit được tạo. Tạo công ty <code>AGENCY</code> → <code>BASIC</code> như cũ.</li><li>AC2. Migration: công ty <code>PERSONAL</code> đang ở <code>BASIC</code> chuyển sang <code>STUDIO_FREE</code>. Công ty Personal đã mua <code>PLUS</code> Agency giữ nguyên tới hết kỳ (grandfather), hết kỳ về <code>STUDIO_FREE</code>.</li><li>AC3. <code>GET /api/v1/billing/plans?agencyId=</code> trả đúng dòng gói theo <code>company_type</code> của agency (không có <code>agencyId</code> → dòng Agency như cũ).</li><li>AC4. Đặt hàng: <code>planCode ∈ {PLUS, STUDIO_PLUS, STUDIO_PRO}</code>; gói phải cùng dòng với công ty, nếu không → <code>BILLING_ORDER_CONFLICT</code>.</li><li>AC5. Thứ hạng: Free(0) &lt; Plus(1) &lt; Pro(2) trong mỗi dòng. UPGRADE chỉ khi hạng đích &gt; hạng hiện tại (hiệu lực); RENEWAL chỉ khi đích = gói hiện tại hoặc đang EXPIRED. Không có hạ cấp (AGENTS.md).</li><li>AC6. Nâng Studio Plus → Studio Pro giữa kỳ (proration): <code>giá = giáPro(chu kỳ chọn) − floor_1000(số tiền đã trả kỳ Plus hiện tại × thời gian còn lại / độ dài kỳ)</code>. Kỳ Pro bắt đầu ngay khi thanh toán; kỳ Plus hiện tại kết thúc tại thời điểm đó; credit tháng đầu của Pro cấp ngay; credit Plus còn lại giữ tới hạn cũ. Nếu phần trừ ≥ giá Pro chu kỳ đã chọn → từ chối, yêu cầu chọn chu kỳ dài hơn. Nếu đang có kỳ FUTURE (đã gia hạn trước) → từ chối nâng giữa kỳ.</li><li>AC7. Hết hạn gói Studio trả phí → <code>STUDIO_FREE</code> + thông báo &quot;Gói Studio đã hết hạn&quot; (không nhắc Basic/Plus Agency).</li><li>AC8. Giới hạn không gian áp dụng cho công ty Personal: tạo / khôi phục không gian thứ N+1 → mã lỗi PLAN_LIMIT hiện có. Công ty Agency: workspace chế độ Personal cũng tính slot (bịt lỗ tạo PERSONAL rồi chuyển AGENCY để lách giới hạn).</li><li>AC9. Giới hạn thành viên: Free/Plus không mời được ai; Pro mời tối đa 2 Creator.</li><li>AC10. Danh sách công ty (<code>GET /agencies</code>) trả <code>planCode</code> hiệu lực đúng (STUDIO_*).</li><li>AC11. Admin revenue nhóm theo gói hiển thị STUDIO_* (sau dòng Agency, thứ tự Free, Plus, Pro).</li><li>AC12. Agency Enterprise giảm lưu trữ 1 TB → 500 GB (version gói mới, giá giữ 3,99tr) để biên xấu nhất đạt 64,7% ≥ 60%. Thuê bao Enterprise đang chạy giữ version cũ tới hết kỳ.</li><li>AC13. Sửa 3 lỗi luồng Personal (review 2026-11-22): (a) form tạo không gian trong công ty Personal khoá chế độ PERSONAL, ẩn chọn chế độ / mời khách hàng / trường doanh nghiệp, tạo xong vào dashboard; (b) trang Công việc ở không gian Personal không tự gắn task vào chiến dịch đầu tiên, hiện ô chọn chiến dịch tuỳ chọn, ẩn banner nghiệm thu chiến dịch; (c) cài đặt không gian của công ty Personal ẩn khối chuyển chế độ Personal/Agency.</li></ul><p>Mô hình giá &amp; lợi nhuận đầy đủ: <code>brandhub-infrastructure/docs/ba/BrandHub_Pricing_Model.xlsx</code>.</p><h2 id="_5-ui-ux-web-mobile-theo-sau" tabindex="-1">5. UI/UX (web; mobile theo sau) <a class="header-anchor" href="#_5-ui-ux-web-mobile-theo-sau" aria-label="Permalink to &quot;5. UI/UX (web; mobile theo sau)&quot;">​</a></h2><ul><li>Trang <code>/subscription/plans</code> với công ty Personal: 3 thẻ Studio, toggle chu kỳ 1/3/6/12 tháng, thẻ hiện tại gắn &quot;Gói hiện tại&quot;, không có ma trận Agency (khách hàng/newsletter). Thẻ Pro khi đang Plus: hiện &quot;Trả chênh lệch ~Xđ&quot; (lấy từ báo giá backend).</li><li>Thẻ công ty / switcher hiển thị tên gói &quot;Studio Plus&quot; thay vì &quot;Plus&quot;.</li><li>Toast vượt giới hạn (upgrade funnel) dẫn tới <code>/subscription/plans?reason=...</code> như hiện có.</li><li><strong>i18n:</strong> key mới trong <code>subscription.json</code> (vi + en, key-parallel): <code>subscription.studio.free|plus|pro.name</code>, <code>subscription.studio.free|plus|pro.tagline</code>, <code>subscription.studio.scope</code>, <code>subscription.studio.proration</code>, <code>subscription.studio.cycleTooShort</code>, <code>subscription.studio.features.*</code> (spaces, members, credits, storage, aiJobs, history, trash), <code>subscription.studio.expiredNotice</code>. Không hardcode chuỗi trong JSX.</li><li><strong>Light/Dark:</strong> chỉ dùng token sẵn có (<code>bg-card</code>, <code>text-muted-foreground</code>, <code>brand-orange</code>, <code>dark:</code> variant); không thêm màu hex mới.</li></ul><h2 id="_6-api-contract" tabindex="-1">6. API Contract <a class="header-anchor" href="#_6-api-contract" aria-label="Permalink to &quot;6. API Contract&quot;">​</a></h2><ul><li><code>GET /api/v1/billing/plans?agencyId={uuid}</code> → <code>BillingPlanResponse[]</code> (thêm field <code>productLine: &quot;AGENCY&quot;|&quot;STUDIO&quot;</code>).</li><li><code>POST /api/v1/billing/agencies/{agencyId}/orders</code> body <code>{ planCode, action, periodMonths }</code> — <code>planCode</code> pattern <code>PLUS|STUDIO_PLUS|STUDIO_PRO</code>. Order lưu <code>amount</code> đã trừ proration và <code>product_snapshot.prorationCredit</code>.</li><li><code>GET /api/v1/billing/agencies/{agencyId}/upgrade-quote?planCode=&amp;periodMonths=</code> → <code>{ price, prorationCredit, amount }</code> (UI hiện số tiền trước khi tạo đơn).</li></ul><h2 id="_7-error-handling" tabindex="-1">7. Error Handling <a class="header-anchor" href="#_7-error-handling" aria-label="Permalink to &quot;7. Error Handling&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tình huống</th><th>Mã lỗi</th></tr></thead><tbody><tr><td>Mua gói khác dòng công ty</td><td><code>BILLING_ORDER_CONFLICT</code></td></tr><tr><td>Hạ cấp / mua gói thấp hơn</td><td><code>BILLING_ORDER_CONFLICT</code></td></tr><tr><td>Proration ≥ giá chu kỳ</td><td><code>BILLING_ORDER_CONFLICT</code> (message: chọn chu kỳ dài hơn)</td></tr><tr><td>Đang có kỳ FUTURE mà nâng giữa kỳ</td><td><code>BILLING_ORDER_CONFLICT</code></td></tr><tr><td>Vượt số không gian / thành viên</td><td>mã PLAN_LIMIT hiện có của <code>AgencyPlanEntitlementService</code></td></tr><tr><td>Gói Studio chưa cấu hình giá</td><td><code>BILLING_NOT_CONFIGURED</code></td></tr></tbody></table><h2 id="_8-edge-cases" tabindex="-1">8. Edge Cases <a class="header-anchor" href="#_8-edge-cases" aria-label="Permalink to &quot;8. Edge Cases&quot;">​</a></h2><ul><li>Webhook về sau khi order hết hạn: giữ luồng REVIEW_REQUIRED hiện có.</li><li>Proration tính lúc tạo đơn; đơn sống ngắn (expires_at) nên lệch vài phút có lợi cho khách — chấp nhận.</li><li>Plus trả trước 12 tháng nâng lên Pro 1 tháng → phần trừ lớn hơn giá → bắt chọn chu kỳ dài hơn.</li><li>Hết hạn khi đang có 3 không gian / 2 Creator (vượt Free): giữ dữ liệu, chặn tạo mới (giống Agency hiện tại).</li><li>Công ty Personal cũ nhận diện bằng <code>logo_icon=&#39;personal-studio&#39;</code> đã được backfill <code>company_type</code> ở migration 2026-11-22.</li></ul><h2 id="_9-ui-states" tabindex="-1">9. UI States <a class="header-anchor" href="#_9-ui-states" aria-label="Permalink to &quot;9. UI States&quot;">​</a></h2><p>Loading (skeleton thẻ gói), lỗi tải catalog (DataErrorState), thẻ disabled khi không mua được (gói thấp hơn / gói hiện tại không gia hạn được), nút loading khi tạo đơn, trạng thái chờ thanh toán SePay (hiện có).</p><h2 id="_10-definition-of-done" tabindex="-1">10. Definition of Done <a class="header-anchor" href="#_10-definition-of-done" aria-label="Permalink to &quot;10. Definition of Done&quot;">​</a></h2><p>AC1–AC11 pass; <code>mvn clean test</code> xanh; <code>npx tsc --noEmit</code> xanh; migration chạy idempotent 2 lần; test.md tick hết; i18n vi/en song song; light/dark kiểm tra.</p><h2 id="_11-out-of-scope" tabindex="-1">11. Out of Scope <a class="header-anchor" href="#_11-out-of-scope" aria-label="Permalink to &quot;11. Out of Scope&quot;">​</a></h2><ul><li>Mobile app (đợt sau, dùng lại API).</li><li>Dùng thử miễn phí / ưu đãi sinh viên.</li><li>Chuyển công ty Personal ↔ Agency (muốn làm agency thì tạo công ty Agency mới).</li><li>Hoàn tiền, hạ cấp.</li><li>Xoá gói <code>PERSONAL</code> (USER scope) cũ — giữ nguyên, không bán.</li></ul>',29)])])}const p=n(d,[["render",c]]);export{u as __pageData,p as default};
